using He_Thong_GYM.Models;using Microsoft.Data.SqlClient;using System.Data;
namespace He_Thong_GYM.DAL;
public sealed class SanPhamDAL
{public async Task<List<SanPham>> LayAsync(){var k=new List<SanPham>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("SELECT MaSP,TenSP,DonGia,SoLuongTon,TrangThai FROM dbo.SanPham ORDER BY MaSP DESC",c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new SanPham{MaSP=r.GetInt32(0),TenSP=r.GetString(1),DonGia=r.GetDecimal(2),SoLuongTon=r.GetInt32(3),TrangThai=r.GetString(4)});return k;}public async Task<int> BanAsync(int tv,int nv,int sp,int sl){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_BanSanPham",c){CommandType=CommandType.StoredProcedure};m.Parameters.AddWithValue("@MaTV",tv);m.Parameters.AddWithValue("@MaNV",nv);m.Parameters.AddWithValue("@MaSP",sp);m.Parameters.AddWithValue("@SoLuong",sl);var o=m.Parameters.Add("@MaHD",SqlDbType.Int);o.Direction=ParameterDirection.Output;await c.OpenAsync();await m.ExecuteNonQueryAsync();return(int)o.Value;}}
